/// The bytes of the placeholder `icon.png`.
///
/// `emb init flatpak --force` replaces an existing `icon.png` only while it is
/// still exactly this, the binary counterpart of [flatpakInitMarker].
final Uint8List flatpakPlaceholderIcon = base64Decode(_placeholderIconBase64);

/// Where ivi-homescreen's build leaves its binary, relative to the build
/// directory.
const defaultEmbedderBin = 'shell/homescreen';

/// What a board target of a generated repo sets over ivi-homescreen's own
/// layer, and the comment that says why.
///
/// That layer turns plugins on and expects ivi-homescreen-plugins checked
/// out beside the embedder, which a generated repo does not have.
const defaultEmbedderTargetDefines = {'DISABLE_PLUGINS': 'ON'};

/// See [defaultEmbedderTargetDefines].
const defaultEmbedderTargetDefinesWhy = [
  "ivi-homescreen's layer turns plugins on and expects",
  'ivi-homescreen-plugins checked out beside the embedder. Off, unless',
  'you add that checkout.',
];

/// ivi-homescreen's own flatpak-sdk targets, `<prefix><arch>`, which an
/// `sdk-<arch>` target of a generated repo extends. They carry what the
/// embedder needs to build against the flatpak SDK: its host
/// wayland-cxx-scanner, since CMake sees the build as a cross build.
const defaultEmbedderSdkTargetPrefix = 'flatpak-sdk-';

/// What the CI workflow installs for ivi-homescreen's flatpak-sdk targets:
/// the host scanner's build dep, which they declare in `host_dev_packages`.
const defaultEmbedderSdkHostPackages = ['libpugixml-dev'];

/// The ivi-homescreen backend a board flatpak is built for when none is
/// named: the one that runs under a compositor.
const defaultEmbedderBackend = 'wayland-egl';

/// A git source pinned at generate time: [rev] is what the manifest builds,
/// [branch] is where that commit was found, kept as a comment beside it so the
/// thing to edit when updating is in view.
class PinnedRepo {
  const PinnedRepo({required this.uri, required this.rev, this.branch});

  final String uri;
  final String rev;
  final String? branch;
}

/// Everything a generated flatpak packaging repo is rendered from.
///
/// Nothing here is read from the machine: the same spec renders the same
/// files anywhere, which is what lets a test pin the templates to the checked
/// in example.
class FlatpakRepoSpec {
  const FlatpakRepoSpec({
    required this.appId,
    required this.id,
    required this.name,
    required this.embedder,
    required this.runtimeVersion,
    required this.embVersion,
    required this.releaseDate,
    this.version = '0.1.0',
    this.summary,
    this.app,
    this.embedderBin,
    this.provider = 'arm-gnu',
    this.flutterVersion = 'stable',
    this.githubCi = true,
    this.targets = const [],
    this.sdkArches = const [],
    this.sdkBasePrefix,
    this.sdkHostPackages = const [],
    this.backend,
    this.targetDefines = const {},
    this.targetDefinesWhy = const [],
  });

  /// Reverse-DNS flatpak app id, e.g. `com.example.MyApp`.
  final String appId;

  /// Manifest id and package name, e.g. `my-app`. Names the manifest file.
  final String id;

  /// Human-readable name for AppStream, the launcher entry
  /// (`package.flatpak.name`) and the README.
  final String name;
  final String version;

  /// The date AppStream gives [version]'s release, `YYYY-MM-DD`: the day the
  /// repo was generated.
  ///
  /// A release needs one. Without it `appstreamcli` warns
  /// (`release-time-missing`) and flatpak drops the element on install
  /// ("Ignoring release element without timestamp or date"), so the version
  /// never reaches a software center. Passed in, not read from the clock
  /// here, so the same spec still renders the same files.
  final String releaseDate;

  /// One-line description for AppStream and the launcher entry
  /// (`package.flatpak.comment`); null leaves a placeholder in AppStream and
  /// no `comment:`.
  final String? summary;

  final PinnedRepo embedder;

  /// The embedder binary, relative to its build directory (`package.bin`).
  ///
  /// Worth naming whenever it is known. Unset, emb looks for the one
  /// executable in the build tree and stops when there are several, so a
  /// repo that leaves it out can fail on an embedder that also builds a
  /// tool or a test.
  final String? embedderBin;

  /// The Flutter app, when it lives in a git repo. Null means the build is
  /// given `--app <dir>`.
  final PinnedRepo? app;

  final String provider;

  final String runtimeVersion;
  final String flutterVersion;

  /// Emit `.github/workflows/flatpak.yml`. Only honored when [app] is set:
  /// with the app outside the repo there is nothing a runner could build, and
  /// a workflow that cannot pass is worse than none.
  final bool githubCi;

  bool get emitsWorkflow => githubCi && app != null;

  /// Board targets, by name. Each is written as
  /// `extends: 'source#<name>'`: the embedder's own target of that name, in
  /// the `.emb/` of the checkout `cross.source` clones. The board alone is
  /// not enough for an embedder that needs more to cross-build (a host tool,
  /// `-dev` packages, backend definitions), and that layer is where it says
  /// so.
  ///
  /// Not checked when the repo is generated: the embedder is not cloned
  /// until the first build.
  final List<String> targets;

  /// Architectures to build against the flatpak SDK (`x86_64`, `aarch64`),
  /// each as a `flatpak-sdk` target named [sdkTargetName]. The host clang
  /// compiles against `org.freedesktop.Sdk` for that architecture, so the
  /// result runs on the runtime it names whatever the build host is, and a
  /// build needs no `-dev` packages on the host.
  final List<String> sdkArches;

  /// The target [arch] is built under: `sdk-<arch>`.
  static String sdkTargetName(String arch) => 'sdk-$arch';

  /// When set, each `sdk-<arch>` target extends the embedder's own
  /// `source#<sdkBasePrefix><arch>`, which knows what the embedder needs to
  /// build against the SDK. Null writes the provider and triple alone.
  final String? sdkBasePrefix;

  /// The `source#` target an `sdk-<arch>` target extends, or null.
  String? sdkBaseTarget(String arch) =>
      sdkBasePrefix == null ? null : 'source#$sdkBasePrefix$arch';

  /// Build-machine packages the CI workflow installs for the SDK target.
  final List<String> sdkHostPackages;

  /// Every target besides `local`: the board targets, then the SDK ones.
  List<String> get allTargets => [
    ...targets,
    for (final a in sdkArches) sdkTargetName(a),
  ];

  /// The SDK target CI builds: the runner's own architecture, so the job
  /// needs neither QEMU nor the embedder's `-dev` packages. Null without one.
  String? get ciSdkTarget =>
      sdkArches.contains('x86_64') ? sdkTargetName('x86_64') : null;

  /// The target the CI workflow builds.
  String get ciTarget => ciSdkTarget ?? 'local';

  /// The backend a board build names (`--backend`). An embedder's layer can
  /// define several, and a flatpak built for more than one is packaged under
  /// `<app_id>.<backend>`, not the id in `metainfo.xml`.
  final String? backend;

  /// `defines:` every board target sets over the embedder's layer, with the
  /// comment lines that say why.
  final Map<String, String> targetDefines;

  /// See [targetDefines].
  final List<String> targetDefinesWhy;

  /// The emb that generated the repo; the workflow installs this one.
  final String embVersion;

  String get manifestName => '$id.emb.yaml';

  /// `emb cross …` for the native build, as the README and the workflow
  /// spell it.
  String get buildCommand => buildCommandFor('local');

  /// `emb cross …` for [target]: `local`, or one of [targets], which also
  /// names [backend].
  String buildCommandFor(String target) => [
    'emb cross $manifestName --target $target',
    if (targets.contains(target) && backend != null) '--backend $backend',
    '--build',
    if (app == null) '--app <path-to-your-flutter-app>',
    '--flatpak',
  ].join(' ');
}

/// The manifest id for a flatpak [appId] with no better name to go on: its
/// last segment, kebab-cased (`com.example.MyApp` → `my-app`).
String idFromAppId(String appId) => kebabCase(appId.split('.').last);

/// Lower-case [name] with `-` at word boundaries: camel humps, `_`, spaces.
String kebabCase(String name) {
  final spaced = name
      .replaceAllMapped(RegExp('([a-z0-9])([A-Z])'), (m) => '${m[1]}-${m[2]}')
      .replaceAll(RegExp('[^A-Za-z0-9]+'), '-');
  return spaced
      .toLowerCase()
      .replaceAll(RegExp('-+'), '-')
      .replaceAll(RegExp(r'^-|-$'), '');
}

/// The repo's binary files: relative path → bytes. Only the placeholder icon.
Map<String, Uint8List> renderFlatpakRepoBinaries(FlatpakRepoSpec spec) => {
  'icon.png': flatpakPlaceholderIcon,
};

/// Renders the repo's text files: relative path → file content.
///
/// No build script is among them. `emb cross <manifest> --build --flatpak` is
/// the build script; a wrapper that adds nothing is a file that rots.
Map<String, String> renderFlatpakRepo(FlatpakRepoSpec spec) => {
  spec.manifestName: _manifest(spec),
  'README.md': _readme(spec),
  '.gitignore': _gitignore(spec),
  'metainfo.xml': _metainfo(spec),
  if (spec.emitsWorkflow) '.github/workflows/flatpak.yml': _workflow(spec),
};

String _header(FlatpakRepoSpec s) =>
    '$flatpakInitMarker (emb ${s.embVersion}).';

/// A YAML scalar: plain when that is unambiguous, single-quoted otherwise.
String _yaml(String value) {
  final plain = RegExp(r'^[A-Za-z0-9_./:@+-]+$').hasMatch(value);
  final ambiguous =
      RegExp(r'^[0-9.+-]+$').hasMatch(value) ||
      const {
        'true',
        'false',
        'null',
        'yes',
        'no',
        'on',
        'off',
        '~',
      }.contains(value.toLowerCase()) ||
      value.startsWith('-') ||
      value.startsWith('@') ||
      value.endsWith(':') ||
      value.contains(': ');
  if (plain && !ambiguous && _loadsAsItself(value)) return value;
  return "'${value.replaceAll("'", "''")}'";
}

/// Whether YAML reads [value], unquoted, as that same string. `1234e56` is a
/// float, `0x1f` an int, `.inf` a float: an abbreviated commit can be any of
/// the first two, and the manifest parser wants a string.
bool _loadsAsItself(String value) {
  try {
    return loadYaml(value) == value;
  } on YamlException {
    return false;
  }
}

/// Escaped for element content and for a quoted attribute value alike.
String _xml(String value) => value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&apos;');

/// `key: value` padded so a trailing comment lines up with its neighbors.
String _line(String indent, String key, String value, [String? comment]) {
  final text = '$indent$key: $value';
  if (comment == null) return text;
  return '${text.padRight(34)} # $comment';
}

List<String> _repo(String key, PinnedRepo repo, String what) => [
  '${'  $key:'.padRight(34)} # $what',
  '    uri: ${_yaml(repo.uri)}',
  _line(
    '    ',
    'rev',
    _yaml(repo.rev),
    repo.branch == null ? null : '${repo.branch} when generated',
  ),
];

String _manifest(FlatpakRepoSpec s) {
  final lines = <String>[
    '# ${_header(s)}',
    '#',
    '# Everything the build needs is named here. The embedder and the app are',
    '# cloned into the workspace below and the Flutter SDK is installed into',
    '# it, so this directory is the whole packaging repo:',
    '#',
    '#   ${s.buildCommand}',
    'id: ${_yaml(s.id)}',
    'type: app',
    _line('', 'workspace', 'workspace', 'relative to this file; git-ignored'),
    _line(
      '',
      'flutter_version',
      _yaml(s.flutterVersion),
      'a branch or a tag; pin a tag to stop it moving',
    ),
    '',
    'cross:',
    _line(
      '  ',
      'provider',
      _yaml(s.provider),
      'required to parse; unused by --target local',
    ),
    ..._repo('source', s.embedder, 'the embedder'),
    if (s.app != null)
      ..._repo('app', s.app!, 'the Flutter app; --app <dir> still wins')
    else ...[
      '  # No app is named, so the build takes --app <dir>. To make the repo',
      '  # self-contained, name the app here:',
      '  # app:',
      '  #   uri: https://example.com/me/my_flutter_app.git',
      '  #   rev: <commit>',
    ],
    '  package:',
    '    name: ${_yaml(s.id)}',
    '    version: ${_yaml(s.version)}',
    if (s.embedderBin != null)
      _line(
        '    ',
        'bin',
        _yaml(s.embedderBin!),
        'the embedder, relative to its build dir',
      )
    else ...[
      '    # Name the embedder binary, relative to its build directory. Unset,',
      '    # emb looks for the one executable there, and stops if the build',
      '    # leaves more than one.',
      '    # bin: <path>',
    ],
    '    files:',
    '      # AppStream metadata, installed under the flatpak prefix (/app).',
    '      metainfo.xml: /share/metainfo/${s.appId}.metainfo.xml',
    '    flatpak:',
    '      app_id: ${s.appId}',
    _line('      ', 'name', _yaml(s.name), "the launcher's name"),
    if (s.summary != null)
      _line('      ', 'comment', _yaml(s.summary!), "the launcher's tooltip"),
    _line('      ', 'icon', 'icon.png', 'a placeholder; replace it'),
    '      runtime_version: ${_yaml(s.runtimeVersion)}',
    if (s.allTargets.isNotEmpty) '  targets:',
    if (s.targets.isNotEmpty) ...[
      "    # Each extends the embedder's own target of that name: the board,",
      '    # plus what the embedder needs to cross-build for it. `source#` is',
      '    # the checkout of cross.source above, which emb clones first.',
      for (final t in s.targets) ...[
        '    ${_yaml(t)}:',
        '      extends: ${_yaml('source#$t')}',
        if (s.targetDefines.isNotEmpty) ...[
          '      defines:',
          for (final why in s.targetDefinesWhy) '        # $why',
          for (final d in s.targetDefines.entries)
            '        ${_yaml(d.key)}: ${_yamlString(d.value)}',
        ],
      ],
    ],
    if (s.sdkArches.isNotEmpty) ...[
      '    # Built against the flatpak SDK rather than this machine: the host',
      '    # clang and lld compile against org.freedesktop.Sdk for that',
      '    # architecture, so the app runs on the runtime named above.',
      if (s.sdkBasePrefix != null) ...[
        "    # Each extends the embedder's own flatpak-sdk target, which",
        '    # brings what it needs to build against the SDK.',
      ],
      for (final a in s.sdkArches) ...[
        '    ${FlatpakRepoSpec.sdkTargetName(a)}:',
        if (s.sdkBaseTarget(a) case final base?)
          '      extends: ${_yaml(base)}',
        '      provider: flatpak-sdk',
        '      triple: $a-flatpak-linux-gnu',
      ],
    ],
  ];
  return '${lines.join('\n')}\n';
}

/// A YAML scalar that is always quoted. A define's value is a string to
/// CMake whatever it looks like: `ON` unquoted is a YAML boolean.
String _yamlString(String value) => "'${value.replaceAll("'", "''")}'";

String _boardSection(FlatpakRepoSpec s) {
  if (s.targets.isEmpty) return '';
  final first = s.targets.first;
  final commands = [for (final t in s.targets) s.buildCommandFor(t)].join('\n');
  final backendNote = s.backend == null
      ? '''
If the embedder's layer defines several backends, add `--backend <name>`. Built
together, each is packaged under its own app id (`${s.appId}.<backend>`), which
is not the id in `metainfo.xml`.
'''
      : '''
`--backend ${s.backend}` is the one backend this flatpak is for. The embedder's
layer can define several, and built together each is packaged under its own app
id (`${s.appId}.<backend>`), which is not the id in `metainfo.xml`.
''';
  return '''

## Build for a board

`${s.manifestName}` also has ${s.targets.length == 1 ? 'a cross target' : 'cross targets'}: ${s.targets.map((t) => '`$t`').join(', ')}. ${s.targets.length == 1 ? 'It extends' : 'Each extends'} the embedder's own
target of that name (`source#$first`), which emb finds in the embedder once it
has cloned it. The name was not checked when this repo was generated; if the
embedder defines no such target, the first build says so.

The runtime has to be the one for the board's architecture, not this machine's,
and flatpak-builder runs that runtime's tools while it packages. So this machine
needs the runtime for that architecture and `qemu-user` registered with
binfmt_misc (`qemu-user-static` on Fedora and Ubuntu). For an aarch64 board:

```sh
flatpak install --user -y flathub org.freedesktop.Platform/aarch64/${s.runtimeVersion} org.freedesktop.Sdk/aarch64/${s.runtimeVersion}
```

Then:

```sh
$commands
```

$backendNote
The first build also downloads the toolchain and the image the sysroot is made
from. Copy the bundle from `workspace/.config/flutter_workspace/cross-build-*/dist/`
to the board and install it there; the board needs the same
`org.freedesktop.Platform` branch.

If you edit a target after it has been built, the next build stops on `emb.lock`
drift; `--update-lock` accepts the change.${s.emitsWorkflow ? '''


The CI workflow builds `--target ${s.ciTarget}` only.''' : ''}
''';
}

String _sdkSection(FlatpakRepoSpec s) {
  if (s.sdkArches.isEmpty) return '';
  final names = [
    for (final a in s.sdkArches) '`${FlatpakRepoSpec.sdkTargetName(a)}`',
  ];
  final refs = [
    for (final a in s.sdkArches) ...[
      'org.freedesktop.Platform/$a/${s.runtimeVersion}',
      'org.freedesktop.Sdk/$a/${s.runtimeVersion}',
    ],
  ].join(' ');
  final commands = [
    for (final a in s.sdkArches)
      s.buildCommandFor(FlatpakRepoSpec.sdkTargetName(a)),
  ].join('\n');
  final foreign = s.sdkArches.any((a) => a != 'x86_64');
  final extendsNote = s.sdkBasePrefix == null
      ? ''
      : "Each extends the embedder's own `${s.sdkBasePrefix}<arch>` target\n"
            '(`source#${s.sdkBasePrefix}<arch>`), which brings what the '
            'embedder needs to\nbuild against the SDK.\n\n';
  final hostNote = s.sdkHostPackages.isEmpty
      ? ''
      : ' and ${s.sdkHostPackages.map((p) => '`$p`').join(', ')} for\nthe host '
            'tools the embedder builds,';
  return '''

## Build against the flatpak SDK

${names.join(', ')} build against `org.freedesktop.Sdk` for that architecture
instead of this machine's libraries. A native build on a host newer than the
runtime can produce a flatpak that will not start, because it needs a newer
glibc than the runtime has; these targets cannot. They also need none of the
embedder's `-dev` packages here.

${extendsNote}This machine compiles with its own clang, so it needs `clang`, `lld` and
`llvm` (the package names on Fedora and Ubuntu),$hostNote plus the
SDK and runtime for each architecture:

```sh
flatpak install --user -y flathub $refs
```
${foreign ? '''

flatpak-builder runs the runtime's tools while it packages, so an architecture
other than this machine's also needs `qemu-user` registered with binfmt_misc
(`qemu-user-static` on Fedora and Ubuntu).
''' : ''}
Then:

```sh
$commands
```
${s.emitsWorkflow && s.ciSdkTarget != null && s.targets.isEmpty ? '''

The CI workflow builds `--target ${s.ciSdkTarget}`.
''' : ''}''';
}

String _readme(FlatpakRepoSpec s) {
  return '''
<!-- ${_header(s)} -->
# ${s.name} flatpak

Packages ${s.name} as a flatpak (`${s.appId}`) with
[emb](https://github.com/toyota-connected/emb_cli). `${s.manifestName}` names the
embedder, ${s.app == null ? '' : 'the app, '}the Flutter SDK and the flatpak runtime, so a build needs nothing
but this directory.

## Build

`flatpak` and `flatpak-builder` must be installed, with the runtime the
manifest names:

```sh
flatpak remote-add --if-not-exists --user flathub https://dl.flathub.org/repo/flathub.flatpakrepo
flatpak install --user -y flathub org.freedesktop.Platform//${s.runtimeVersion} org.freedesktop.Sdk//${s.runtimeVersion}
```

Then:

```sh
${s.buildCommand}
```

The first build clones the embedder${s.app == null ? '' : ' and the app'} and installs the Flutter SDK into
`workspace/`; later builds reuse them. The bundle is written to
`workspace/.config/flutter_workspace/cross-build-*/dist/`.

## Install and run

```sh
flatpak install --user workspace/.config/flutter_workspace/cross-build-*/dist/${s.appId}_stable_*.flatpak
flatpak run ${s.appId}
```
${_boardSection(s)}${_sdkSection(s)}
## Before publishing

- `icon.png` is a placeholder. Replace it with a 256×256 PNG of your own.
- `metainfo.xml` has no license. `project_license` is a `TODO` on purpose: a
  wrong license is worse than a missing one, and flathub will not accept the
  placeholder.
- `rev:` values in `${s.manifestName}` are the commits that were current when
  this repo was generated. Update them deliberately; the comment beside each
  names the branch it came from.
''';
}

String _gitignore(FlatpakRepoSpec s) =>
    '''
# ${_header(s)}
# The workspace emb builds in: clones, the Flutter SDK, build trees, bundles.
workspace/
build/
dist/
''';

String _metainfo(FlatpakRepoSpec s) =>
    '''
<?xml version="1.0" encoding="UTF-8"?>
<!-- ${_header(s)} -->
<component type="desktop-application">
  <id>${_xml(s.appId)}</id>
  <name>${_xml(s.name)}</name>
  <summary>${_xml(s.summary ?? 'TODO: one line describing ${s.name}')}</summary>
  <!-- Required: appstreamcli fails the flatpak build without one. -->
  <description>
    <p>${_xml(s.summary ?? 'TODO: a paragraph describing ${s.name}.')}</p>
  </description>
  <metadata_license>CC0-1.0</metadata_license>
  <!-- TODO: the app's license as an SPDX expression. Not inferred: a wrong
       license is worse than a missing one. A flathub submission needs it. -->
  <project_license>TODO</project_license>
  <launchable type="desktop-id">${_xml(s.appId)}.desktop</launchable>
  <releases>
    <!-- The day this repo was generated. Set it to the release's own. -->
    <release version="${_xml(s.version)}" date="${_xml(s.releaseDate)}"/>
  </releases>
</component>
''';

/// How the workflow installs the emb that generated the repo.
///
/// A release is on pub.dev under its version. A development build is not, so
/// the only thing that can be named is the repository, and the file says so.
List<String> _installEmb(String version) {
  if (!version.contains('-')) {
    return ['        run: dart pub global activate emb_cli $version'];
  }
  return [
    '        # Generated by an unreleased emb ($version), which pub.dev does',
    '        # not have. Replace with a release once one carries `emb init`:',
    '        #   dart pub global activate emb_cli <version>',
    '        run: >',
    '          dart pub global activate --source git',
    '          https://github.com/toyota-connected/emb_cli.git',
  ];
}

String _workflow(FlatpakRepoSpec s) {
  final lines = <String>[
    '# ${_header(s)}',
    '#',
    '# Builds the flatpak natively on the runner. Deliberately plain: no',
    '# caching, one job. Add what your project needs.',
    'name: flatpak',
    '',
    'on:',
    '  push:',
    '    branches: [main]',
    '  pull_request:',
    '  workflow_dispatch:',
    '',
    '# The build runs code from the embedder, the app and the Flutter SDK.',
    '# None of it needs to write to this repo.',
    'permissions:',
    '  contents: read',
    '',
    'jobs:',
    '  flatpak:',
    '    runs-on: ubuntu-latest',
    '    steps:',
    '      - uses: actions/checkout@v4',
    '        with:',
    '          persist-credentials: false',
    '      - uses: dart-lang/setup-dart@v1',
    if (s.ciSdkTarget == null) ...[
      '      # cmake and ninja build the embedder; libsystemd-dev is for a',
      '      # native dependency of emb itself.',
      '      - name: Install build tools',
      '        run: |',
      '          sudo apt-get update -qq',
      r'          sudo apt-get install -y -qq flatpak flatpak-builder binutils \',
      '            cmake ninja-build libsystemd-dev',
      '      # TODO: the -dev packages your embedder links against. A native',
      '      # build uses the host libraries, and emb cannot know them from',
      '      # here.',
      '      # - name: Install embedder dependencies',
      '      #   run: sudo apt-get install -y -qq <packages>',
    ] else ...[
      '      # cmake and ninja build the embedder, clang, lld and llvm compile',
      '      # it against the flatpak SDK, whose libraries it links, so no',
      '      # -dev packages are needed. libsystemd-dev is for a native',
      '      # dependency of emb itself.',
      if (s.sdkHostPackages.isNotEmpty) ...[
        '      # ${s.sdkHostPackages.join(', ')}: for host tools the embedder',
        '      # builds on this machine.',
      ],
      '      - name: Install build tools',
      '        run: |',
      '          sudo apt-get update -qq',
      r'          sudo apt-get install -y -qq flatpak flatpak-builder binutils \',
      [
        '            cmake ninja-build libsystemd-dev clang lld llvm',
        ...s.sdkHostPackages,
      ].join(' '),
    ],
    '      - name: Install the flatpak runtime',
    '        run: |',
    r'          flatpak remote-add --if-not-exists --user \',
    '            flathub https://dl.flathub.org/repo/flathub.flatpakrepo',
    r'          flatpak install --user -y --noninteractive flathub \',
    '            org.freedesktop.Platform//${s.runtimeVersion} \\',
    '            org.freedesktop.Sdk//${s.runtimeVersion}',
    '      - name: Install emb',
    ..._installEmb(s.embVersion),
    '      - name: Build the flatpak',
    '        run: >',
    '          emb cross ${s.manifestName} --target ${s.ciTarget} --build',
    '          --flatpak',
    '      - uses: actions/upload-artifact@v4',
    '        with:',
    '          name: flatpak',
    '          path: >-',
    '            workspace/.config/flutter_workspace/cross-build-*/dist/*.flatpak',
    '          if-no-files-found: error',
  ];
  return '${lines.join('\n')}\n';
}
